const GRAPH_NODES = ['Attention', 'Transformers', 'LLMs', 'Latent Space', 'Diffusion'];

// ─── Helper: click a phase by its name (scoped to phaseNav) ───────────────
async function clickPhase(page: any, phaseName: string) {
  const nav = page.locator('[class*="phaseNav"]');
  await nav.getByText(phaseName, { exact: true }).click();
  await page.waitForTimeout(200);
}

// ─── Helper: click a tool card in the synthesis grid ──────────────────────
async function clickToolCard(page: any, toolTitle: string) {
  const grid = page.locator('[class*="synthesisGrid"]');
  await grid.locator('[class*="toolTitle"]').filter({ hasText: toolTitle }).click();
  await page.waitForTimeout(200);
}

// ─── Helper: wait for tool modal ──────────────────────────────────────────
async function getToolModal(page: any) {
  // Two overlays may exist (share + tool). Return the last one, which is the tool modal.
  const overlay = page.locator('[class*="shareOverlay"]').last();
  await expect(overlay).toBeVisible({ timeout: 5000 });
  return overlay.locator('[class*="shareModal"]').last();
}

